recipes.code:
{
  "inputs": [
    {
      "id": "scrapeunblocker-key",
      "type": "promptString",
      "description": "Your ScrapeUnblocker API key (get one at https://app.scrapeunblocker.com).",
      "password": true
    }
  ],
  "servers": {
    "scrapeunblocker": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "scrapeunblocker-mcp@0.1.2"
      ],
      "env": {
        "SCRAPEUNBLOCKER_KEY": "${input:scrapeunblocker-key}"
      }
    }
  }
}
